/*
 * hp_fonts.h -- font API for the HP Prime graphics library: two families
 * with per-glyph metrics, drawable into the screen OR the selected GROB
 * (every draw goes through hp_pixel, which targets the current grob).
 *
 *   mono -- Cascadia Code Light (OFL-1.1, wght=350), fixed-width cell
 *   prop -- Montserrat (OFL-1.1), proportional advances, per-size
 *           weight: 12px wght=450, 16px+ Regular
 *
 * Both are pre-rasterized 4-bit GRAYSCALE (alpha coverage, 16 levels)
 * bitmaps at 12/16/24/32 px (rt/hp_fonts_data.c, generated by
 * rt/tools/fontgen2.py); drawing alpha-blends onto the target via
 * hp_pixel_a.  hp_font_mono/prop pick the closest pre-rendered size.
 *
 * Coordinate convention: hp_font_draw(f, x, y, s, c) treats (x,y) as the
 * top-left of the LINE box (like hp_text); the baseline sits at
 * y + f->ascent.  hp_font_w returns the pen advance (sum of per-glyph
 * advances), hp_font_h the line height.
 */
#ifndef HP_FONTS_H
#define HP_FONTS_H

#include "hp_gfx.h"            /* hp_color */

typedef struct hp_glyph {
    unsigned char w, h;        /* bitmap width/height in px (0 = no ink) */
    signed char   xoff;        /* bitmap left edge relative to the pen x */
    signed char   yoff;        /* bitmap top row relative to the line top y */
    unsigned char adv;         /* advance width in px */
    unsigned short bits;       /* byte offset into the font's bitmap pool */
} hp_glyph;

typedef struct hp_font {
    unsigned char size;        /* nominal size in px */
    unsigned char line_h;      /* line height in px (ascent + descent) */
    signed char   ascent;      /* baseline offset from the line top */
    unsigned char first;       /* first glyph char code */
    unsigned char last;        /* last glyph char code */
    const hp_glyph *glyphs;    /* (last-first+1) entries, index = ch-first */
    const unsigned char *bits; /* packed 1-bit bitmaps (rows, LSB-first) */
} hp_font;

/* font handles: nearest pre-rendered size; never NULL */
hp_font *hp_font_mono(int size);       /* Unifont (monospace) */
hp_font *hp_font_prop(int size);       /* Montserrat (proportional) */

/* accessors into the generated tables (rt/hp_fonts_data.c), index 0..3.
 * Functions, not globals: TCC's ARM linker cannot relocate a GOT access
 * to a non-static global (see hp_fonts_data.c). */
const hp_font *hp_font_prop_data(int i);
const hp_font *hp_font_mono_data(int i);

/* metrics */
int hp_font_h(const hp_font *f);                /* line height (px) */
int hp_font_w(const hp_font *f, const char *s); /* text width (px) */
int hp_font_advance(const hp_font *f, int ch);  /* per-char advance (px) */

/* draw into the current target (screen or selected GROB) */
void hp_font_draw(const hp_font *f, int x, int y, const char *s, hp_color c);
void hp_font_draw_bg(const hp_font *f, int x, int y, const char *s,
                     hp_color fg, hp_color bg);

#endif /* HP_FONTS_H */
